import emotionStyled from '@emotion/styled';

import type { GridContainerType, GridItemSize } from './Grid';

const calcSize = (size?: GridItemSize) => {
  if (size === undefined) return undefined;
  return size === 'auto' ? 'auto' : `${(size / 12) * 100}%`;
};

export const StyledGridItem = emotionStyled('div', {
  shouldForwardProp: (propName) =>
    !['$xs', '$sm', '$md', '$lg', '$xl'].includes(propName),
})<{
  $xs: GridItemSize;
  $sm?: GridItemSize;
  $md?: GridItemSize;
  $lg?: GridItemSize;
  $xl?: GridItemSize;
}>(({ $xs, $sm, $md, $lg, $xl }) => ({
  display: 'flex',
  flexBasis: calcSize($xs),
  paddingLeft: '0.5rem',
  paddingRight: '0.5rem',
  '@media (min-width: 37.5rem)': {
    flexBasis: calcSize($sm) ?? calcSize($xs),
  },
  '@media (min-width: 56.25rem)': {
    flexBasis: calcSize($md) ?? calcSize($sm) ?? calcSize($xs),
  },
  '@media (min-width: 75rem)': {
    flexBasis: calcSize($lg) ?? calcSize($md) ?? calcSize($sm) ?? calcSize($xs),
  },
  '@media (min-width: 96rem)': {
    flexBasis:
      calcSize($xl) ??
      calcSize($lg) ??
      calcSize($md) ??
      calcSize($sm) ??
      calcSize($xs),
  },
}));

export const StyledGridContainer = emotionStyled('div', {
  shouldForwardProp: (propName) => !['$sidebar', '$type'].includes(propName),
})<{ $sidebar: boolean; $type: GridContainerType }>(({ $sidebar, $type }) => ({
  display: 'flex',
  flexWrap: 'wrap',
  margin: $type === 'contained' ? 'auto' : '0 1rem',
  width: $type === 'contained' ? '77.5rem' : 'auto',
  '@media (min-width: 56.25rem)': {
    margin: $type === 'fluid' ? '0 1.5rem' : '0 auto',
    paddingLeft: $sidebar && $type === 'fluid' ? '5rem' : undefined,
  },
}));
